from pathlib import Path
import json
p=Path(__file__).resolve().parents[1]; f=p/'data/buildings.json'; a=json.loads(f.read_text()); by={x['slug']:x for x in a}
rows=[
('vederko','https://zombi.at.ua/board/postrojki/sdelaj_sam/vederko/23-1-0-824','https://zombie-island.moy.su/blog/vederko_postroyka_zombie_farm_zombi_manija/2013-06-05-1929','11.06.2013',{'Получение и маршрут':'По Zombie-island, после квеста «Раскопки» Ведёрко можно купить за 50 000 монет; после строительства оно открывает путь на Песочный остров. Цена продажи 0 монет, 300 опыта за покупку и 650 всего.','Стадии':'1: 5 красного пластилина, 10 вёдер, 20 скакалок (150 опыта); 2: 5 палочек, 15 песка, 5 фантиков (200 опыта). Подписи сверены по Zombie-island: на ZOMBIA подписи alt материалов ошибочны.','Под недостроенным у друзей':'Песок, Песочная коллекция, металлолом, бесплатные лопаты, опыт и монеты — перечень Zombie-island, без указания вероятностей.'}),
('pesochnitsa','https://zombi.at.ua/board/postrojki/vysokij_uroven_zombi_ferma/pesochnica/13-1-0-825','https://zombie-island.moy.su/blog/pesochnica_postroyka_zombie_farm_zombi_mania/2013-06-05-1930','11.06.2013',{'Доступ':'По Zombie-island, Песочница уже находится недостроенной на Песочном острове, купить её нельзя; после строительства создаёт песочные декорации.','Стадии':'Zombie-island считает 1-ю стадию построенной по умолчанию; 2-я: 10 резины, 35 времени, 5 фантиков (150 опыта); 3-я: 25 золотой пыли, 30 рогаток, 5 палочек (200 опыта). ZOMBIA перечисляет две стадии с материалами как 1-ю и 2-ю; количества совпадают, нумерация отличается. Подписи alt на ZOMBIA ошибочны.','Примеры рецептов':'Стена: 5 песка и 4 блока; окно: 5 песка и 10 досок; двери: 4 песка и 4 фанеры. Это не полный список рецептов в статье.'}),
('derevo-lyubvi','https://zombi.at.ua/board/postrojki/ruletki/derevo_ljubvi/33-1-0-802','https://zombie-island.moy.su/blog/derevo_ljubvi_postroyka_zombie_farm_mania/2013-03-26-1826','09.05.2013',{'Доступ':'Указаны награда за квест «Посевная три», цена 450 000 монет и невозможность продажи; порядок получения и покупки дополнительно не проверен. 300 опыта за покупку, 1150 всего.','Стадии':'1: 1000 брёвен, 500 секвойи, 500 брёвен пальмы; 2: по 500 малины, арбузов и рамбутанов; 3: 1000 мира, 1000 любви, 10 шёлка; 4: по 500 черепуши, глазных яблок и мандаринов; 5: 10 язей, 10 золотых рыбок и 15 лепестков розы. Подписи материалов сверены по Zombie-island.','Аист и рулетка':'Аист: 1 аленький цветочек и 1001 любовь. Рулетка за 25 малины: статья одновременно говорит «ежедневно» и «раз в 13 минут»; точный интервал нуждается в проверке. Перечислены монеты, опыт, супер-урожай на день и любовь.'}),
('admiral','https://zombi.at.ua/board/postrojki/ruletki/admiral/33-1-0-738','https://zombie-island.moy.su/blog/admiral_postroyka_zombie_farm_zombi_manija/2013-02-21-1771','24.02.2013',{'Стоимость и доступ':'По Zombie-island, купить за 1 000 000 монет после квеста «Суп», продажа 100 000; за покупку 300 опыта, всего 700.','Стадии':'1: 15 пороха, 10 угля, 30 глазных яблок; 2: 10 колоннад, 15 гаек, 50 черепуши. Названия сверены по подписанным изображениям Zombie-island.','Рулетка и бонус':'За 1 глазной суп: супер-поиск на 1, 2 или 3 дня, йодированная соль или быстрый фрукт; за 5 глазных яблок: элементы коллекций рыбака, пиратской, футбольной или быстрый фрукт. Супер-поиск активируется со склада; новый бонус заменяет действующий, по тексту источника.'}),
('shkatulka','https://zombi.at.ua/board/postrojki/novinki_zombi_ferma/shkatulka/15-1-0-841','https://zombie-island.moy.su/blog/skazka_zadaniya_prokhozhdenie_kvesty_igry_zombie_farm_mania/2013-06-21-1998','22.06.2013',{'Получение':'Обе статьи относят Шкатулку к награде квеста «Сказка». Статья квеста перечисляет 30 черники с косточкой, 50 вишни и 15 железных сердец в Вожде; награда — 1 Шкатулка.','Оговорка о рецептах':'ZOMBIA показывает рецепты преимущественно картинками с ошибочными alt-подписями; ингредиенты без дополнительной сверки не расшифровываются.'})]
for slug,u,v,date,fields in rows:
 x=by[slug]
 for s in x['sources']:
  if s['url']==u:s['label']='ZOMBIA: отдельная карточка прочитана; размещена '+date
 if not any(z['url']==v for z in x['sources']):x['sources'].append({'url':v,'label':'Zombie-island: подписанная отдельная статья; связан с ЗомбиСити'})
 rid='verified-2013-article-'+slug
 if not any(z.get('original_id')==rid for z in x['prior_records']):x['prior_records'].append({'original_id':rid,'original_category':'Сверка отдельных статей','version':'историческая браузерная версия; сеть и редакция требуют уточнения','date':date+' — дата размещения страницы ZOMBIA; дата её последней редакции неизвестна','fields':fields,'confidence':'Фанатские источники; независимость не установлена, сведения могли меняться. Подписи alt на ZOMBIA ненадёжны; Zombie-island связан с ЗомбиСити.'})
f.write_text(json.dumps(a,ensure_ascii=False,indent=2)+'\n')
s=p/'data/sources.json';d=json.loads(s.read_text())
for x in d:
 if x['number']==5:
  t=' Прочитаны отдельные карточки Ведёрка, Песочницы, Дерева любви, Адмирала и Шкатулки; даты размещения 2013 года, даты редакции неизвестны.'
  if t not in x['summary']:x['summary']+=t
s.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
